const assert=require('node:assert/strict');
const fs=require('node:fs');
const vm=require('node:vm');
const path=require('node:path');
const source=fs.readFileSync(path.join(__dirname,'../../index.html'),'utf8');
const start=source.indexOf('const EVOLVEFIT_CLOUD_QUEUE_KEY =');
const end=source.indexOf('/* ---- Sincronização segura',start);
assert.ok(start>0&&end>start);
const map=new Map();
const ctx={localStorage:{getItem:k=>map.get(k)||null,setItem:(k,v)=>map.set(k,v),removeItem:k=>map.delete(k)}};
vm.createContext(ctx);
vm.runInContext(source.slice(start,end)+'\nthis.read=cloudQueueRead;this.write=cloudQueueWrite;this.clear=cloudQueueClear;',ctx);
ctx.write({uid:'A',payload:{_json:'a'}});
ctx.write({uid:'B',payload:{_json:'b'}});
assert.equal(ctx.read('A').payload._json,'a');
assert.equal(ctx.read('B').payload._json,'b');
ctx.clear('A');
assert.equal(ctx.read('A'),null);
assert.equal(ctx.read('B').payload._json,'b','limpar A não elimina edições pendentes de B');
map.set('evolvefit_cloud_pending_v1',JSON.stringify({uid:'legacy',payload:{_json:'old'}}));
assert.equal(ctx.read('B').payload._json,'b');
assert.equal(ctx.read('legacy').payload._json,'old','a fila antiga continua recuperável pela sua conta');
assert.equal(ctx.read('C'),null,'a fila antiga nunca é enviada a outra conta');
ctx.clear('legacy');
assert.equal(map.has('evolvefit_cloud_pending_v1'),false);
assert.equal(ctx.read('B').payload._json,'b');
console.log('Filas por conta: escritas offline independentes e migração de fila antiga.');
